def fewestEdits(n, edges):
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    comps = n
    surplus = 0
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            surplus += 1
        else:
            parent[ra] = rb
            comps -= 1
    return surplus + comps - 1
